from pathlib import Path
class Reader:
    def checked(self, path):
        p = Path(path).resolve()
        p.relative_to(Path('/srv/data').resolve())
        return p
    def read(self, path):
        return open(self.checked(path))
def unsafe(path): return path
reader = Reader()

@mcp.tool()
def load(path): return reader.read(path)

